---@class ActSignInData
ActSignInData  = class("ActSignInData")
function ActSignInData:initialize()
    ---第几天
    self.nowDay = 0
    ---总天数
    self.totalDays = 0
    ---开始时间
    self.beginTime = 0
    ---结束时间
    self.endTime = 0
    ---补签费用
    self.expPay = 0
    ---@type table<number,number> SignInState.CanNotSignIn
    self.stateTable ={}
    ---@type table<number,table<number,RewardData>>
    self.dayAwardsTable={}
end

---@param configData act_day_sign_config_cell
function ActSignInData:SetDataByConfig(configData)
    self.beginTime = configData.begintime
    self.endTime = configData.endtime
    self.expPay = configData.exppay
    local dayAwards= stringSplit(configData.dayawards,':')
    local dayAwardNums= stringSplit(configData.awardnums,':')
    self.totalDays = #dayAwards
    if #dayAwards > #dayAwardNums then
        logError("act_day_sign  每日奖励串  和  对应奖励数量串不对应  ")
    end
    for i = 1, #dayAwards do
        self.dayAwardsTable[i]={}
        local awards = stringSplit(dayAwards[i],",")
        local awardNums = stringSplit(dayAwardNums[i],",")
        if #awards < #awardNums then
            logError("act_day_sign  每日奖励串  和  对应奖励数量串不对应  ")
        end
        for j = 1, #awards do
            ---@type RewardData
            local rewardData=RewardData()
            rewardData:SetDataIdNum(tonumber(awards[j]),tonumber(awardNums[j]))
            self.dayAwardsTable[i][j]=rewardData
        end
    end
end

---@param msg SC_ActSign
function ActSignInData:SetDataByMsgActSign(msg)
    self.nowDay =msg.nowday
    for i = 1, #msg.actSigns do
        local state = SignInState.CanNotSignIn
        if msg.actSigns[i]==0then--  0未1可补签2已签 长度为总天数
            if  i==self.nowDay  then
                state = SignInState.NoSignIn
            elseif i < self.nowDay then
                state = SignInState.Retroactive
            end
        elseif msg.actSigns[i] == 1 then
            --state = SignInState.Retroactive
            state = SignInState.SignedIn
        elseif msg.actSigns[i] == 2 then
            state = SignInState.SignedIn
        end
        self.stateTable[i] = state
    end
end

function ActSignInData:GetExpPay()
    return self.expPay
end


function ActSignInData:GetStateByDay(day)
    return self.stateTable[day]
end

---@return RewardData
function ActSignInData:GetRewardData(day,index)
    if self.dayAwardsTable[day] and  self.dayAwardsTable[day][index] then
        local rewardData= self.dayAwardsTable[day][index]
        return rewardData
    else
        --log("没有该数据",day,index)
        return nil
    end
end

function ActSignInData:GetNowDay()
    return self.nowDay
end

function ActSignInData:GetTotalDays()
    return self.totalDays
end

---@class ActSignInDataManager
ActSignInDataManager = class("ActSignInDataManager")
function ActSignInDataManager:initialize()
    ---@type table<number,ActSignInData>
    self.ActSignInTable={}
    self:InitItemData()
end

function ActSignInDataManager:Get()
    if self._instance == nil then
        self._instance = ActSignInDataManager()
    end
    return self._instance
end

function ActSignInDataManager:SetCurActSignInId(actSignInId)
    self.actSignInId=actSignInId
end

---@return ActSignInData
function  ActSignInDataManager:GetCurActSignIn()
    if  self.actSignInId and self.ActSignInTable[self.actSignInId] then
        return self.ActSignInTable[self.actSignInId]
    else
        logError("   没有设置当前的签到活动ID  或者该活动ID在表格中不存在 ",tostring(self.actSignInId))
    end
end

function ActSignInDataManager:InitItemData()
    ---@type act_day_sign_config
    local act_day_sign_config = ClientDataManager:Get():GetDataTable(ConfigNames.act_day_sign_config)
    local actDaySignTable= act_day_sign_config:GetConfigData()
    for key, daySignData in pairs(actDaySignTable) do
        local actSignInData = ActSignInData()
        actSignInData:SetDataByConfig(daySignData)
        self.ActSignInTable[daySignData.C_ID] = actSignInData
    end
end

function ActSignInDataManager:GetNowDay()
    if self:GetCurActSignIn() then
        return self:GetCurActSignIn():GetNowDay()
    end
    return 0
end

function ActSignInDataManager:GetTotalDays()
    if self:GetCurActSignIn() then
        return self:GetCurActSignIn():GetTotalDays()
    end
    return 0
end

---@param msg SC_ActSign
function ActSignInDataManager:SetDataByMsgActSign(msg)
    if self.ActSignInTable[msg.actId] then
        self.ActSignInTable[msg.actId]:SetDataByMsgActSign(msg)
    end
end

function ActSignInDataManager:SetActSignIsResetFlag(value)
    self.IsRefresh=value
end
function ActSignInDataManager:GetActSignIsResetFlag()
    return self.IsRefresh
end